import unittest

from hourglass.errors import ProjectError
from hourglass.gaps import find_gaps
from hourglass.models import Span


class GapTests(unittest.TestCase):
    def test_gap_between_spans(self):
        worked = [Span(540, 720), Span(780, 1020)]
        result = find_gaps(worked, Span(540, 1020))
        self.assertEqual(result, [
            "gap 12:00-13:00 (60 min)"
        ])

    def test_edges(self):
        result = find_gaps([Span(600, 660)], Span(540, 720))
        self.assertEqual(result, [
            "gap 09:00-10:00 (60 min)",
            "gap 11:00-12:00 (60 min)"
        ])

    def test_nothing_worked(self):
        result = find_gaps([], Span(540, 600))
        self.assertEqual(result, [
            "gap 09:00-10:00 (60 min)"
        ])

    def test_full_cover_has_no_gaps(self):
        worked = [Span(540, 700), Span(600, 720)]
        result = find_gaps(worked, Span(540, 720))
        self.assertEqual(result, [])

    def test_outside_hours_raises(self):
        with self.assertRaises(ProjectError):
            find_gaps([Span(500, 600)], Span(540, 720))
